{
  "summary": "驗證專案任務的建立與更新 API (`POST /api/projects/{pid}/tasks` 及 `PATCH /api/tasks/{tid}`) 中的 `title` 與 `priority` 欄位驗證規則。",
  "acceptance_criteria": [
    "title 為必填欄位，長度限制為 1 至 100 字元（包含邊界）。",
    "title 長度為 100 字元時應被接受（回傳 201 或 200）。",
    "title 長度超過 101 字元或為空白時應回傳 422 錯誤，且不得回傳 5xx 錯誤。",
    "priority 必須為整數，範圍為 1 至 5（包含邊界），預設值為 3。",
    "priority 為 1 與 5 時應被接受，若為 0 或 6 則應回傳 422 錯誤。"
  ]
}

{
  "requirement_id": "REQ-002",
  "cases": [
    {
      "id": "TC-1",
      "title": "驗證 title 邊界長度 100 字元與 priority 邊界值 1 及 5 的建立與更新",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project A\"} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"a\" * 100, \"priority\": 1} as alice",
        "PATCH /api/tasks/{tid} with {\"priority\": 5} as alice"
      ],
      "expected": "title 長度為 100 字元時應被接受（回傳 201 或 200）。priority 為 1 與 5 時應被接受"
    },
    {
      "id": "TC-2",
      "title": "驗證 title 超過 101 字元或為空白時回傳 422 錯誤且不得回傳 5xx 錯誤",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project B\"} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"a\" * 101, \"priority\": 3} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"   \", \"priority\": 3} as alice"
      ],
      "expected": "title 長度超過 101 字元或為空白時應回傳 422 錯誤，且不得回傳 5xx 錯誤。"
    },
    {
      "id": "TC-3",
      "title": "驗證 priority 為 0 或 6 時應回傳 422 錯誤",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project C\"} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Valid Title\", \"priority\": 0} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Valid Title\", \"priority\": 6} as alice"
      ],
      "expected": "若為 0 或 6 則應回傳 422 錯誤。"
    }
  ]
}

